/// message (see [`Slot::is_kept_by`]).
fn drop_thinking_without_own_block(content: &mut Vec<WireBlock>) {
    let keep: Vec<bool> = content
        .iter()
        .map(|b| match b.slot {
            Some(slot) if b.is_thinking() => content.iter().any(|o| slot.is_kept_by(o)),
            _ => true,
